function summarizeWindow(events, nowMs, windowMs, cap) {
  const windowStart = nowMs - windowMs;
  const seenIds = new Set();
  const modelCounts = new Map();
  let used = 0;
  let minTs = Infinity;

  for (const ev of events) {
    if (ev == null) continue;

    const id = ev.id;
    if (typeof id === 'string' && id.length > 0) {
      if (seenIds.has(id)) continue;
      seenIds.add(id);
    }

    if (
      typeof ev.ts !== 'number' ||
      !Number.isFinite(ev.ts) ||
      ev.ts < windowStart ||
      ev.ts > nowMs ||
      ev.provider !== 'opencode-go' ||
      ev.error ||
      typeof ev.model !== 'string' ||
      ev.model.toLowerCase().endsWith('-free')
    ) {
      continue;
    }

    used += 1;
    if (ev.ts < minTs) minTs = ev.ts;

    const model = ev.model.replace(/^opencode-go\//, '').toLowerCase();
    modelCounts.set(model, (modelCounts.get(model) || 0) + 1);
  }

  const byModel = Object.fromEntries(
    [...modelCounts.keys()]
      .sort()
      .map((model) => [model, modelCounts.get(model)])
  );

  return {
    used,
    remaining: Math.max(0, cap - used),
    pct: Math.round((used / cap) * 1000) / 10,
    overCap: used > cap,
    oldestExpiresAt: used === 0 ? null : minTs + windowMs,
    byModel,
  };
}
